  }

  /// Parses one chain entry from yaml: either the string shorthand or a map
  /// with `provider`/`model` plus optional overrides.
  factory ModelRef.fromYaml(Object? node, {String? role}) {
    switch (node) {
      case String value:
        return ModelRef.parse(value, role: role);
      case YamlMap map:
