        'non-empty string',
      );
    }
    return value.trim();
  }

  static int? _optionalInt(YamlMap map, String key, String? role) {
    final value = map[key];
    if (value == null) return null;
    if (value is! int || value <= 0) {
      throw ConfigException(
        '"$key"${role == null ? '' : ' in role "$role"'} must be a '
        'positive integer',
